def build_navigation_plan(
    entities: list[dict[str, Any]],
    links: list[dict[str, Any]],
    entry_ids: list[str],
    page_config: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Assign page/appendix/boundary using fixed evidence and configured quotas."""
    config = page_config or DEFAULT_PAGE_CONFIG
    page_limits = config["page_limits"]
    ordinary_file_limit = int(page_limits["ordinary_file"])
    core_file_limit = int(page_limits["core_file"])
    adjacent_file_limit = int(page_limits["adjacent_file"])
    core_entry_limit = int(page_limits["core_per_entry"])
    adjacent_entry_limit = int(page_limits["adjacent_per_entry"])
    facts = _graph_facts(entities, links)
    by_id: dict[str, dict[str, Any]] = facts["by_id"]
    entries = {value for value in entry_ids if value in by_id}
    entry_owners = {ancestor for entry in entries for ancestor in _ancestors(entry, by_id) if by_id[ancestor]["kind"] != "file"}
    entry_direct: set[str] = set()
    for entry in entries:
        entry_direct.update(facts["outgoing"].get(entry, set()))
        entry_direct.update(facts["incoming"].get(entry, set()))
    selected_pages: set[str] = {entity["id"] for entity in entities if entity["kind"] == "file"}
    boundary_ids = {entity["id"] for entity in entities if entity["kind"] == "boundary"}
    selected_pages.update(boundary_ids)
    candidates_by_path: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for entity in entities:
        if _eligible(entity, entries):
            candidates_by_path[entity["path"]].append(entity)
    rank_kwargs = {"entry_ids": entries, "entry_owners": entry_owners, "entry_direct": entry_direct, "facts": facts}
    for values in candidates_by_path.values():
        values.sort(key=lambda value: _rank(value, **rank_kwargs))

    clusters: list[dict[str, Any]] = []
    core_paths: set[str] = set()
    neighbor_ids_all: set[str] = set()
    adjacent_paths: set[str] = set()
    selected_key_count_by_path: dict[str, int] = defaultdict(int)
    for entry_id in sorted(entries):
        entry = by_id[entry_id]
        if not _eligible(entry, entries):
            clusters.append({"entry_id": entry_id, "core_page_ids": [], "neighbor_page_ids": [], "landing_page_id": next((value for value in _ancestors(entry_id, by_id) if by_id[value]["kind"] == "file"), None)})
            continue
        same_path = candidates_by_path.get(entry["path"], [])
        core_pool: list[dict[str, Any]] = [entry] if _eligible(entry, entries) else []
        for ancestor_id in _ancestors(entry_id, by_id):
            ancestor = by_id[ancestor_id]
            if ancestor["kind"] != "file" and _eligible(ancestor, entries):
                core_pool.append(ancestor)
        direct_same = [by_id[value] for value in facts["outgoing"].get(entry_id, set()) | facts["incoming"].get(entry_id, set()) if value in by_id and by_id[value]["path"] == entry["path"] and _eligible(by_id[value], entries)]
        core_pool.extend(sorted(direct_same, key=lambda value: _rank(value, **rank_kwargs)))
        entry_parent = entry.get("parent_id")
        core_pool.extend(value for value in same_path if value.get("parent_id") == entry_parent)
        core_ids: list[str] = []
        for value in core_pool:
            if len(core_ids) >= core_entry_limit:
                break
            if value["id"] in core_ids:
                continue
            if value["id"] in selected_pages:
                core_ids.append(value["id"])
                continue
            if selected_key_count_by_path[value["path"]] >= core_file_limit:
                continue
            core_ids.append(value["id"])
            selected_pages.add(value["id"])
            selected_key_count_by_path[value["path"]] += 1
        core_paths.update(by_id[value]["path"] for value in core_ids)

        neighbor_pool: list[dict[str, Any]] = []
        for core_id in core_ids:
            for neighbor_id in facts["outgoing"].get(core_id, set()) | facts["incoming"].get(core_id, set()):
                neighbor = by_id.get(neighbor_id)
                if neighbor and neighbor["path"] != entry["path"] and _eligible(neighbor, entries):
                    neighbor_pool.append(neighbor)
        neighbor_pool.sort(key=lambda value: _rank(value, **rank_kwargs))
        neighbor_ids: list[str] = []
        for value in neighbor_pool:
            if len(neighbor_ids) >= adjacent_entry_limit:
                break
            if value["id"] in neighbor_ids or value["id"] in selected_pages:
                continue
            if value["path"] in core_paths or selected_key_count_by_path[value["path"]] >= adjacent_file_limit:
                continue
            neighbor_ids.append(value["id"])
            selected_pages.add(value["id"])
            selected_key_count_by_path[value["path"]] += 1
        neighbor_ids_all.update(neighbor_ids)
        adjacent_paths.update(by_id[value]["path"] for value in neighbor_ids)
        adjacent_paths.difference_update(core_paths)
        clusters.append({"entry_id": entry_id, "core_page_ids": core_ids, "neighbor_page_ids": neighbor_ids})

    # Every non-core source file receives no more than its configured ordinary
    # or adjacent quota.  Ranking and tie breaks remain entirely deterministic.
    for path, values in sorted(candidates_by_path.items()):
        if path in core_paths:
            continue
        limit = adjacent_file_limit if path in adjacent_paths else ordinary_file_limit
        for value in values:
            if selected_key_count_by_path[path] >= limit:
                break
            if value["id"] not in selected_pages:
                selected_pages.add(value["id"])
                selected_key_count_by_path[path] += 1

    owner_by_entity: dict[str, str] = {}
    decisions: list[dict[str, Any]] = []
    file_page_by_path = {entity["path"]: entity["id"] for entity in entities if entity["kind"] == "file"}
    for entity in entities:
        entity_id = entity["id"]
        if entity_id in boundary_ids:
            classification = "boundary"
            owner = entity_id
        elif entity_id in selected_pages:
            classification = "page"
            owner = entity_id
        else:
            classification = "appendix"
            owner = next((ancestor for ancestor in _ancestors(entity_id, by_id) if ancestor in selected_pages and by_id[ancestor]["kind"] != "file"), file_page_by_path.get(entity["path"]))
            if not owner:
                raise AuditError(f"appendix entity has no deterministic owner: {entity_id}")
        owner_by_entity[entity_id] = owner
        evidence = []
        if entity_id in entries:
            evidence.append("explicit-entry")
        if entity_id in entry_owners:
            evidence.append("entry-lexical-owner")
        if entity_id in entry_direct:
            evidence.append("entry-direct-relation")
        if facts["cross_degree"].get(entity_id, 0):
            evidence.append("cross-file-reference")
        if entity.get("is_public_or_exported"):
            evidence.append("public-or-exported")
        if entity.get("hard_exclusion"):
            evidence.append(f"hard-exclusion:{entity['hard_exclusion']}")
        decisions.append(
            {
                "entity_id": entity_id,
                "classification": classification,
                "owner_page_id": owner,
                "rank_evidence": evidence or ["fixed-order-default"],
                "cross_file_degree": facts["cross_degree"].get(entity_id, 0),
                "total_degree": facts["total_degree"].get(entity_id, 0),
            }
        )

    page_count_by_path: dict[str, int] = defaultdict(int)
    for entity_id in selected_pages - boundary_ids:
        entity = by_id[entity_id]
        if entity["kind"] != "file":
            page_count_by_path[entity["path"]] += 1
    quota_errors = []
    for path, count in sorted(page_count_by_path.items()):
        limit = core_file_limit if path in core_paths else (adjacent_file_limit if path in adjacent_paths else ordinary_file_limit)
        if count > limit:
            quota_errors.append({"path": path, "count": count, "limit": limit})
    for cluster in clusters:
        if len(cluster["core_page_ids"]) > core_entry_limit or len(cluster["neighbor_page_ids"]) > adjacent_entry_limit:
            quota_errors.append(
                {
                    "entry_id": cluster["entry_id"],
                    "reason": "entry-cluster-quota",
                    "core_count": len(cluster["core_page_ids"]),
                    "core_limit": core_entry_limit,
                    "adjacent_count": len(cluster["neighbor_page_ids"]),
                    "adjacent_limit": adjacent_entry_limit,
                }
            )
    return {
        "schema_version": 3,
        "algorithm": "human-code-unit-navigation-v3-configured",
        "page_limits": dict(page_limits),
        "classifications": sorted(PAGE_CLASSIFICATIONS),
        "decisions": decisions,
        "entity_owner_pages": owner_by_entity,
        "page_entity_ids": sorted(selected_pages - boundary_ids),
        "boundary_entity_ids": sorted(boundary_ids),
        "entry_clusters": clusters,
        "core_paths": sorted(core_paths),
        "adjacent_paths": sorted(adjacent_paths),
        "page_count_by_path": dict(sorted(page_count_by_path.items())),
        "quota_errors": quota_errors,
        "status": "passed" if not quota_errors else "failed",
    }

def prepare_vault(root: Path, output: Path) -> None:
    """Remove only generator-owned files and preserve Agent/user notes."""
    root.mkdir(parents=True, exist_ok=True)
    ownership = root / ".ckb-generated-files.json"
    if ownership.is_file():
        record = json_load(ownership)
        for relative in record.get("files", []):
            path = root / str(relative)
            if path.is_file():
                path.unlink()
            elif path.is_dir():
                safe_rmtree(path, root)
    else:
        for name in GENERATED_TOP_LEVEL:
            (root / name).unlink(missing_ok=True)
        for name in ("pages", "logseq"):
            path = root / name
            if path.exists():
                safe_rmtree(path, root)
    for name in (*NOTE_DIRECTORIES, *FEEDBACK_DIRECTORIES):
        (root / name).mkdir(parents=True, exist_ok=True)

def write_generated_ownership(root: Path, generated: list[Path]) -> dict[str, Any]:
    files = sorted(path.relative_to(root).as_posix() for path in generated if path.is_file())
    record = {"schema_version": 1, "status": "ready", "files": files}
    json_write(root / ".ckb-generated-files.json", record)
    return record

def _payload_from_package(package: Path, temporary: Path) -> Path:
    package = package.expanduser().resolve()
    if package.is_dir():
        return package
    if not package.is_file() or package.suffix.casefold() != ".zip":
        raise CkbError(f"Obsidian plugin package must be a directory or ZIP: {package}")
    with zipfile.ZipFile(package) as archive:
        if archive.testzip():
            raise CkbError(f"Obsidian plugin ZIP CRC failed: {package}")
        names = set(archive.namelist())
        prefix = ""
        if "manifest.json" not in names:
            candidates = sorted(name for name in names if name.endswith("/manifest.json"))
            if len(candidates) != 1:
                raise CkbError("Obsidian plugin ZIP must contain one manifest.json")
            prefix = candidates[0][:-len("manifest.json")]
        for name in REQUIRED_FILES:
            member = prefix + name
            if member not in names:
                raise CkbError(f"Obsidian plugin ZIP is missing {name}")
            target = temporary / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive.read(member))
        for name in OPTIONAL_FILES:
            member = prefix + name
            if member in names:
                (temporary / name).write_bytes(archive.read(member))
    return temporary

def _validate_payload(root: Path) -> dict[str, Any]:
    missing = [name for name in REQUIRED_FILES if not (root / name).is_file()]
    if missing:
        raise CkbError(f"Obsidian plugin payload is incomplete: {missing}")
    manifest = json_load(root / "manifest.json")
    if manifest.get("id") != PLUGIN_ID:
        raise CkbError(f"unexpected Obsidian plugin id: {manifest.get('id')}")
    version = str(manifest.get("version") or "").strip()
    if not version:
        raise CkbError("Obsidian plugin manifest has no version")
    return manifest

def _registered_payload(registry: Path | None = None) -> tuple[dict[str, Any], Path]:
    registry = (registry or default_obsidian_plugin_registry()).expanduser().resolve()
    if not registry.is_file():
        raise CkbError("no active Obsidian plugin package is registered; run obsidian-plugin register")
    record = json_load(registry)
    payload = Path(str(record.get("payload") or "")).resolve()
    manifest = _validate_payload(payload)
    if str(manifest["version"]) != str(record.get("version")):
        raise CkbError("registered Obsidian plugin payload version drifted")
    return record, payload

def remove_obsidian_plugin(output: Path) -> dict[str, Any]:
    output = output.resolve()
    vault = output / "human"
    destination = vault / ".obsidian" / "plugins" / PLUGIN_ID
    if destination.exists():
        safe_rmtree(destination, vault / ".obsidian" / "plugins")
    community_path = vault / ".obsidian" / "community-plugins.json"
    if community_path.is_file():
        community = json_load(community_path)
        if isinstance(community, list):
            json_write(community_path, [value for value in community if value != PLUGIN_ID])
    (output / "workspace-meta" / "obsidian-plugin.json").unlink(missing_ok=True)
    from .output_contract import remove_output_contract

    remove_output_contract(vault)
    return {"schema_version": 1, "status": "removed", "plugin_id": PLUGIN_ID, "output": str(output)}

def deploy_registered_plugin_if_available(vault: Path, output: Path | None = None) -> dict[str, Any]:
    registry = default_obsidian_plugin_registry()
    if not registry.is_file():
        return {"status": "not-registered"}
    result = deploy_obsidian_plugin_to_vault(vault, registry)
    if output is not None:
        from .output_contract import project_output_contract

        result["output_contract"] = project_output_contract(output, vault)
    return result

def _journal_lock(root: Path) -> Iterator[None]:
    root.mkdir(parents=True, exist_ok=True)
    lock = root / ".lock"
    deadline = time.monotonic() + 5.0
    descriptor: int | None = None
    while descriptor is None:
        try:
            descriptor = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.write(descriptor, str(os.getpid()).encode("ascii"))
        except FileExistsError:
            try:
                if time.time() - lock.stat().st_mtime > 30:
                    lock.unlink(missing_ok=True)
                    continue
            except FileNotFoundError:
                continue
            if time.monotonic() >= deadline:
                raise CkbError(f"operation journal is busy: {lock}")
            time.sleep(0.05)
    try:
        yield
    finally:
        if descriptor is not None:
            os.close(descriptor)
        lock.unlink(missing_ok=True)

def _read_shard(path: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    if not path.is_file():
        return records
    for line_number, line in enumerate(path.read_text(encoding="utf-8-sig").splitlines(), start=1):
        if not line.strip():
            continue
        try:
            value = json.loads(line)
        except json.JSONDecodeError as exc:
            raise CkbError(f"invalid operation journal JSONL at {path}:{line_number}: {exc}") from exc
        if not isinstance(value, dict):
            raise CkbError(f"operation journal record must be an object: {path}:{line_number}")
        records.append(value)
    return records

def _state(root: Path) -> dict[str, Any]:
    path = root / "state.json"
    if not path.is_file():
        return {
            "schema_version": OPERATION_JOURNAL_SCHEMA_VERSION,
            "dropped_records": 0,
            "expired_records": 0,
            "deduplicated_records": 0,
        }
    value = json_load(path)
    if not isinstance(value, dict):
        raise CkbError(f"operation journal state must be an object: {path}")
    return value

def _prune_expired(root: Path, today: date, state: dict[str, Any]) -> None:
    cutoff = _retention_cutoff(today)
    for path in sorted(root.glob("*.jsonl")):
        matched = _SHARD_NAME.fullmatch(path.name)
        if not matched:
            continue
        shard_date = date.fromisoformat(matched.group(1))
        if shard_date >= cutoff:
            continue
        state["expired_records"] = int(state.get("expired_records", 0)) + len(_read_shard(path))
        path.unlink()

def _all_events(root: Path) -> list[dict[str, Any]]:
    events: list[dict[str, Any]] = []
    for path in sorted(root.glob("*.jsonl")):
        if _SHARD_NAME.fullmatch(path.name):
            events.extend(_read_shard(path))
    return events

def _relative_evidence(output: Path, result: dict[str, Any]) -> list[str]:
    evidence: set[str] = set()
    for key in sorted(_EVIDENCE_KEYS):
        value = result.get(key)
        values = value if isinstance(value, list) else [value]
        for candidate in values:
            if not isinstance(candidate, str) or not candidate.strip():
                continue
            path = Path(candidate)
            if not path.is_absolute():
                path = output / path
            try:
                resolved = path.resolve()
            except OSError:
                continue
            if not resolved.exists() or not path_inside(resolved, output):
                continue
            evidence.add(resolved.relative_to(output).as_posix())
    return sorted(evidence)[:8]

def _operation_type(command: str) -> str | None:
    root = command.split(":", 1)[0]
    if root in {"init", "run", "build-chunk", "review-chunk", "review-pack", "merge", "finalize", "human-refresh", "reindex", "migrate", "relink"}:
        return "compile"
    if root in {"query", "retrieve", "brief", "keyword-benchmark", "context", "coverage", "entity", "neighbors", "source", "changes", "path", "explain", "status"}:
        return "query"
    if root == "maintain":
        return "maintenance"
    if command == "gaps:list":
        return "query"
    if command == "gaps:audit":
        return "audit"
    if command in {"gaps:create", "gaps:resolve"}:
        return "record"
    if root == "audit" or command in {"reference:audit", "feedback:audit", "agent-policy:check", "migrate:audit"}:
        return "audit"
    if root == "record" or command in {
        "reference:ingest",
        "reference:review",
        "reference:rollback",
        "feedback:create",
        "feedback:resolve",
        "workspace:session-start",
        "workspace:session-finish",
        "automation:review",
    }:
        return "record"
    return None

def record_cli_operation(args: Any, result: Any) -> dict[str, Any] | None:
    if str(getattr(args, "command", "")) == "operations" or not isinstance(result, dict):
        return None
    if result.get("operation_journal_recorded") is True:
        return None
    output_value = getattr(args, "out", None)
    if output_value is None:
        return None
    output = Path(output_value).resolve()
    if not (output / "state.json").is_file():
        return None
    command = _command_name(args)
    operation = _operation_type(command)
    if operation is None:
        return None
    status = str(result.get("status") or "completed")
    evidence = _relative_evidence(output, result)
    return record_operation(output, operation, command, status, evidence)

def list_operations(output: Path, operation: str | None = None, result_status: str | None = None, limit: int = 50) -> dict[str, Any]:
    if operation is not None and operation not in OPERATION_TYPES:
        raise CkbError(f"unsupported operation filter: {operation}")
    if limit < 1 or limit > 500:
        raise CkbError("operation list limit must be between 1 and 500")
    events = _all_events(_root(output))
    selected = [
        item
        for item in events
        if (operation is None or item.get("operation") == operation)
        and (result_status is None or item.get("result_status") == result_status)
    ]
    return {
        "schema_version": OPERATION_JOURNAL_SCHEMA_VERSION,
        "status": "ready",
        "filters": {"operation": operation, "result_status": result_status},
        "count": len(selected),
        "operations": selected[-limit:][::-1],
    }

def _event_errors(item: dict[str, Any], path: Path, line_number: int) -> list[str]:
    prefix = f"{path.name}:{line_number}"
    errors = []
    if set(item) != _EVENT_FIELDS:
        errors.append(f"{prefix}: fields differ from the fixed operation schema")
        return errors
    if item.get("schema_version") != OPERATION_JOURNAL_SCHEMA_VERSION:
        errors.append(f"{prefix}: schema version mismatch")
    if item.get("operation") not in OPERATION_TYPES:
        errors.append(f"{prefix}: unsupported operation type")
    if not isinstance(item.get("command"), str) or not _SAFE_TOKEN.fullmatch(item["command"]):
        errors.append(f"{prefix}: invalid command token")
    if not isinstance(item.get("result_status"), str) or not _SAFE_TOKEN.fullmatch(item["result_status"]):
        errors.append(f"{prefix}: invalid result status token")
    if not isinstance(item.get("event_id"), str) or not item["event_id"].startswith("operation-"):
        errors.append(f"{prefix}: invalid event id")
    if not isinstance(item.get("recorded_at_utc"), str) or len(item["recorded_at_utc"]) != 20:
        errors.append(f"{prefix}: invalid recorded timestamp")
    evidence = item.get("evidence_paths")
    if not isinstance(evidence, list) or len(evidence) > 8:
        errors.append(f"{prefix}: evidence_paths must be a bounded list")
    else:
        for value in evidence:
            if not isinstance(value, str):
                errors.append(f"{prefix}: evidence path must be text")
                continue
            relative = PurePosixPath(value)
            if relative.is_absolute() or ".." in relative.parts:
                errors.append(f"{prefix}: evidence path escapes OUTPUT")
    return errors

def _runtime_binding(output: Path) -> tuple[Path, Path]:
    record_path = output / "workspace-meta/agent-protocol.json"
    record = json_load(record_path) if record_path.is_file() else {}
    python = Path(str(record.get("python") or sys.executable)).resolve()
    ckb = Path(str(record.get("ckb") or _default_ckb())).resolve()
    return python, ckb
